# --- Mock Git Integration ---

class GitIntegration:
    def __init__(self):
        self.repo_state: Dict[str, Dict[str, Any]] = {}  # repo_id -> {branch, commits, files}

    def init_repo(self, repo_id: str, branch: str = "main") -> bool:
        if repo_id in self.repo_state:
            return False
        self.repo_state[repo_id] = {
            "branch": branch,
            "commits": [],
            "files": {},
            "review_sessions": []
        }
        return True

    def commit(self, repo_id: str, user_id: str, message: str, files: Dict[str, str]) -> str:
        if repo_id not in self.repo_state:
            raise ValueError("Repository not initialized")
        commit_id = str(uuid.uuid4())
        commit = {
            "id": commit_id,
            "user_id": user_id,
            "message": message,
            "timestamp": datetime.utcnow().isoformat(),
            "files": files
        }
        self.repo_state[repo_id]["commits"].append(commit)
        self.repo_state[repo_id]["files"].update(files)
        return commit_id

    def get_latest_commit(self, repo_id: str) -> Optional[Dict]:
        if repo_id not in self.repo_state:
            return None
        commits = self.repo_state[repo_id]["commits"]
        return commits[-1] if commits else None

    def link_review_session(self, repo_id: str, session_id: str):
        if repo_id in self.repo_state:
            self.repo_state[repo_id]["review_sessions"].append(session_id)

# --- Real-Time Communication Layer (Mock) ---

class RealTimeBroker:
    def __init__(self):
        self.subscribers: Dict[str, Set[asyncio.Queue]] = {}  # session_id -> set of queues

    async def subscribe(self, session_id: str, queue: asyncio.Queue) -> bool:
        if session_id not in self.subscribers:
            self.subscribers[session_id] = set()
        self.subscribers[session_id].add(queue)
        return True

    async def unsubscribe(self, session_id: str, queue: asyncio.Queue):
        if session_id in self.subscribers:
            self.subscribers[session_id].discard(queue)

    async def broadcast(self, session_id: str, event: Dict[str, Any]):
        if session_id in self.subscribers:
            for queue in self.subscribers[session_id]:
                await queue.put(event)

